<template><div class="page"><div class="page-head"><div><h1 class="page-title">粉丝管理</h1><div class="page-subtitle">查看并筛选当前公众号关注用户</div></div><div class="toolbar"><el-input v-model="query.nickname" placeholder="昵称" clearable @change="load"/><el-button @click="load">刷新</el-button><el-button type="primary" @click="sync">同步粉丝</el-button></div></div><div class="surface table-surface"><el-table :data="list" v-loading="loading"><el-table-column label="头像" width="72"><template #default="{row}"><el-avatar :src="row.headimgurl">{{(row.nickname||row.openid||'?').slice(0,1)}}</el-avatar></template></el-table-column><el-table-column prop="nickname" label="昵称"><template #default="{row}"><span v-if="row.nickname">{{row.nickname}}</span><span v-else class="muted">未授权</span></template></el-table-column><el-table-column prop="openid" label="OpenID" show-overflow-tooltip/><el-table-column label="性别" width="70"><template #default="{row}">{{['未知','男','女'][row.sex]||'未知'}}</template></el-table-column><el-table-column prop="city" label="城市"><template #default="{row}"><span v-if="row.city||row.province">{{row.province}}{{row.city}}</span><span v-else class="muted">未授权</span></template></el-table-column><el-table-column prop="subscribeScene" label="关注来源" width="100" show-overflow-tooltip/><el-table-column prop="qrSceneStr" label="场景值" width="120" show-overflow-tooltip/><el-table-column prop="remark" label="备注" width="120" show-overflow-tooltip/><el-table-column prop="subscribeTime" label="关注时间"/><el-table-column label="标签"><template #default="{row}"><el-tag v-for="tag in row.tagidList||[]" :key="tag" size="small">{{tag}}</el-tag></template></el-table-column></el-table><div class="pager"><el-pagination layout="prev,pager,next" :total="total" :page-size="query.limit" @current-change="page=>{query.page=page;load()}"/></div></div></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'@/api/console';const list=ref([]),total=ref(0),loading=ref(false),query=reactive({page:1,limit:10,nickname:''});async function load(){loading.value=true;try{const r=await api.followers(query);list.value=r.page.list;total.value=r.page.totalCount}finally{loading.value=false}}async function sync(){await api.syncFollowers();ElMessage.success('同步任务已启动')}onMounted(load)</script><style scoped>.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>
